import React from 'react';
import {useParams,Link,Navigate} from 'react-router-dom';
import Seo from '../components/Seo';
import Icon from '../components/Icon';
import {projects} from '../data/site';
export default function ProjectDetail(){const {slug}=useParams();const p=projects.find(x=>x.slug===slug);if(!p)return <Navigate to="/projets" replace/>;return <><Seo title={p.name} path={`/projets/${p.slug}`} description={p.intro} type="article"/>
<section className="project-detail-hero" style={{'--accent':p.accent}}><div><p className="eyebrow"><span/>{p.kind} · {p.year}</p><h1>{p.name}</h1><p>{p.headline}</p><a className="primary-action" href={p.url} target="_blank" rel="noopener noreferrer">Voir le projet <Icon name="arrow"/></a></div><div className="project-detail-visual">{p.image?<img src={p.image} alt=""/>:<div className={`project-ui project-ui--${p.slug}`}><div className="project-ui-bar"><i/><i/><i/></div><strong>{p.name}</strong><small>{p.headline}</small></div>}<div className="detail-glass"><span>{p.roles[0]}</span><span>{p.stack[0]}</span></div></div></section>
<section className="project-detail-body"><aside className="glass-card"><p>Rôle</p>{p.roles.map(x=><span key={x}>{x}</span>)}<p>Technologies / terrain</p>{p.stack.map(x=><span key={x}>{x}</span>)}</aside><article><div><small>Contexte</small><h2>{p.challenge}</h2></div><div><small>Approche</small><p>{p.approach}</p></div><div><small>Ce que le projet m’a fait travailler</small><p>{p.detail}</p></div></article></section>
<section className="case-next"><Link to="/projets">← Tous les projets</Link><Link to="/expertise">Compétences <Icon name="arrow" size={15}/></Link></section></>}
